{
  "justification": "Health dominates and social safety concerns are prominent, pointing to strong Care/Harm salience, while EU/Europe and Immigration highlight group-boundary and national-solidarity (Loyalty) motives; crime/terror, environment, and inequality map to Authority, Sanctity, and fairness concerns. Because the survey records salience but not direction, weights reflect the breadth and prominence of related issues rather than specific policy stances.",
  "foundations": [
    {
      "foundation": "care",
      "basis": "NHS/Hospitals/Healthcare; Ageing population/Social care; Poverty/Inequality; Housing; Education/Schools; Crime/Violence; Pollution/Environment; Drug abuse; Animal welfare",
      "weight": 0.3
    },
    {
      "foundation": "loyalty",
      "basis": "Common Market/EU/Europe; Immigration; Defence/Foreign affairs/International terrorism; Scottish/Welsh Assembly/Devolution; Nuclear weapons/Disarmament; Race relations; Countryside/Rural life",
      "weight": 0.2
    },
    {
      "foundation": "authority",
      "basis": "Crime/Law and order/Violence/Vandalism; Defence/Foreign affairs/International terrorism; Morality/Individual behaviour/Lifestyle; Lack of faith in govt/politics; Education/Schools; Public services in general",
      "weight": 0.1
    },
    {
      "foundation": "sanctity",
      "basis": "Pollution/Environment; Drug abuse; Morality/Individual behaviour/Lifestyle; Animal welfare; NHS/Healthcare (body/health purity concerns)",
      "weight": 0.07
    },
    {
      "foundation": "equality",
      "basis": "Poverty/Inequality; Low pay/Minimum wage/Fair wages; NHS/Hospitals/Healthcare (universalism); Education/Schools; Housing; Pensions/Social security; Race relations",
      "weight": 0.18
    },
    {
      "foundation": "proportionality",
      "basis": "Economy/Economic situation; Unemployment/Factory closure/Lack of industry; Taxation; Inflation/Prices; Privatisation/Nationalisation; Pound/Exchange rate; Petrol prices/Fuel; Trade unions/Strikes",
      "weight": 0.15
    }
  ]
}
